import{_ as t,o as a,c as o,a5 as s}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"Technical Implementation Plan — Workspace Realtime Chat Channels, Threads, Mentions, Slash References, Scheduled Messages & 1:1 Voice Calls (workspace-chat-and-voice-calls)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/04-task-chat-vault/workspace-chat-and-voice-calls/plan.md","filePath":"feature/modules/04-task-chat-vault/workspace-chat-and-voice-calls/plan.md"}'),c={name:"feature/modules/04-task-chat-vault/workspace-chat-and-voice-calls/plan.md"};function n(r,e,i,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="technical-implementation-plan-—-workspace-realtime-chat-channels-threads-mentions-slash-references-scheduled-messages-1-1-voice-calls-workspace-chat-and-voice-calls" tabindex="-1">Technical Implementation Plan — Workspace Realtime Chat Channels, Threads, Mentions, Slash References, Scheduled Messages &amp; 1:1 Voice Calls (<code>workspace-chat-and-voice-calls</code>) <a class="header-anchor" href="#technical-implementation-plan-—-workspace-realtime-chat-channels-threads-mentions-slash-references-scheduled-messages-1-1-voice-calls-workspace-chat-and-voice-calls" aria-label="Permalink to &quot;Technical Implementation Plan — Workspace Realtime Chat Channels, Threads, Mentions, Slash References, Scheduled Messages &amp; 1:1 Voice Calls (`workspace-chat-and-voice-calls`)&quot;">​</a></h1><h2 id="_1-system-components-touched-repositories" tabindex="-1">1. System Components &amp; Touched Repositories <a class="header-anchor" href="#_1-system-components-touched-repositories" aria-label="Permalink to &quot;1. System Components &amp; Touched Repositories&quot;">​</a></h2><p>Consolidates the technical architecture for <code>workspace-chat-collaboration</code>, <code>chat-attachments</code>, <code>chat-mention-inbox</code>, <code>chat-rich-composer</code>, <code>chat-scheduled-messages</code>, <code>chat-slash-reference</code>, <code>chat-thread-layout</code>, <code>chat-voice-calls</code> as specified in <a href="./spec.html">spec.md</a>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Layer / Repository</th><th style="text-align:left;">Key Classes, Services, Schemas &amp; Components</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway (<code>brandhub-api-gateway</code>)</strong></td><td style="text-align:left;"><code>GatewayConfig.java</code> (<code>/api/v1/workspaces/*/chat/**</code> + STOMP WebSocket <code>/ws/**</code>)</td></tr><tr><td style="text-align:left;"><strong>Backend / Worker Services</strong></td><td style="text-align:left;"><code>ChatController.java</code>, <code>ChatChannelController.java</code>, <code>ChatChannelMessageController.java</code>, <code>ChatAttachmentController.java</code>, <code>ChatPreferenceController.java</code>, <code>ChatScheduleController.java</code>, <code>ChatCallController.java</code></td></tr><tr><td style="text-align:left;"><strong>Persistence, Cache &amp; Brokers</strong></td><td style="text-align:left;">MongoDB <code>chat_channels</code>, <code>chat_messages</code>, <code>chat_channel_reads</code>, <code>chat_read_states</code>, <code>chat_attachments</code>, <code>chat_scheduled_messages</code>, <code>chat_calls</code>; AWS S3 chat attachments; PostgreSQL <code>user_notifications</code></td></tr><tr><td style="text-align:left;"><strong>Web Frontend (<code>brandhub-web</code>)</strong></td><td style="text-align:left;"><code>pages/chat/index.tsx</code>, <code>pages/chat/components/{ChatWorkspace,ChatRichComposer,ChatResizableThread,ChatSlashMenu,ChatAttachmentComposer,ChatRepositoryPicker,ChatScheduledPanel,ChatCallBar}.tsx</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App (<code>brandhub-mobile-app</code>)</strong></td><td style="text-align:left;"><code>src/screens/chat/ChatScreen.tsx</code>, <code>src/components/chat/ChatChannelPicker.tsx</code>, <code>src/services/chatService.ts</code> (<code>@stomp/stompjs</code> 7.5)</td></tr><tr><td style="text-align:left;"><strong>i18n &amp; Theme Assets</strong></td><td style="text-align:left;"><code>chat.{channels,composer,threads,mentions,slash,scheduled,calls,preferences}.*</code> in <code>src/i18n/locales/{vi,en}/chat.json</code>; Mobile <code>src/i18n/locales/en.json</code> + <code>src/i18n/locales/vi/common.json</code> &amp; <code>src/theme/tokens.ts</code></td></tr></tbody></table><h2 id="_2-core-technical-design-data-model-invariants" tabindex="-1">2. Core Technical Design &amp; Data Model Invariants <a class="header-anchor" href="#_2-core-technical-design-data-model-invariants" aria-label="Permalink to &quot;2. Core Technical Design &amp; Data Model Invariants&quot;">​</a></h2><ul><li><strong>Channel-Scoped STOMP Topics + MongoDB Persistence:</strong> Messages persist to <code>chat_messages</code> first, then fan out over <code>/topic/workspaces/{workspaceId}/channels/{channelId}</code> with deterministic message IDs.</li><li><strong>Server-Authoritative Call State Machine:</strong> Signaling travels over STOMP + REST heartbeats while media audio streams over ephemeral RTC tokens minted per <code>callId</code>.</li></ul><h2 id="_3-end-to-end-data-control-flow" tabindex="-1">3. End-to-End Data &amp; Control Flow <a class="header-anchor" href="#_3-end-to-end-data-control-flow" aria-label="Permalink to &quot;3. End-to-End Data &amp; Control Flow&quot;">​</a></h2><ol><li><strong>Ingress &amp; Identity Propagation:</strong> Requests pass through <code>brandhub-api-gateway</code> (<code>InboundSecurityWebFilter</code> -&gt; <code>JwtAuthFilterGatewayFilterFactory</code> -&gt; <code>RateLimitGatewayFilterFactory</code>), stripping external header spoofing and injecting verified <code>X-User-Id</code>, <code>X-Request-Id</code>, and role claims.</li><li><strong>Authorization &amp; Invariant Validation:</strong> Downstream controllers and services re-verify canonical role permissions (<code>Owner, Manager, Creator, Client</code>) and Agency/Workspace tenant membership against authoritative database state before mutating data or dispatching async jobs.</li><li><strong>Atomic Persistence &amp; Event Fan-Out:</strong> State transitions commit atomically across MongoDB <code>chat_channels</code>, <code>chat_messages</code>, <code>chat_channel_reads</code>, <code>chat_read_states</code>, <code>chat_attachments</code>, <code>chat_scheduled_messages</code>, <code>chat_calls</code>; AWS S3 chat attachments; PostgreSQL <code>user_notifications</code> using optimistic (<code>@Version</code> / <code>expectedRevision</code>) or pessimistic locks, emitting outbox/WebSocket/<code>pg_notify</code> events after commit.</li><li><strong>Client State Reconciliation:</strong> <code>brandhub-web</code> and <code>brandhub-mobile-app</code> consume typed <code>ApiResponse&lt;T&gt;</code> envelopes, update user/tenant-scoped <code>TanStack Query</code> caches, and render localized UI states in Light and Dark themes.</li></ol><h2 id="_4-sequential-implementation-rollout-order" tabindex="-1">4. Sequential Implementation &amp; Rollout Order <a class="header-anchor" href="#_4-sequential-implementation-rollout-order" aria-label="Permalink to &quot;4. Sequential Implementation &amp; Rollout Order&quot;">​</a></h2><ol><li><strong>Phase 1 — Database / Storage / Config Baseline:</strong> Apply additive migrations in <code>database/init/init-postgres-v2.sql</code> and <code>database/migrations/postgres/*.sql</code> (plus MongoDB/Neo4j/Redis indexes) with repeat-run idempotency.</li><li><strong>Phase 2 — Domain Services &amp; Security Guards:</strong> Implement core service logic, cryptographic/concurrency helpers, and internal service-to-service contracts.</li><li><strong>Phase 3 — Public REST / WebSocket / Worker Endpoints:</strong> Wire controllers, consumers, and exception handlers returning standardized <code>ErrorCode</code> payloads.</li><li><strong>Phase 4 — Web &amp; Mobile UI Surfaces:</strong> Deliver responsive components, accessibility/keyboard navigation, and state transitions without mock data fallbacks.</li><li><strong>Phase 5 — Key-Parallel i18n (<code>vi</code>/<code>en</code>) &amp; Light/Dark Theme Audit:</strong> Synchronize translation namespaces and verify semantic color tokens across Light and Dark modes.</li><li><strong>Phase 6 — Multi-Layer Verification:</strong> Execute unit, integration, contract, and browser/mobile E2E suites documented in <a href="./test.html">test.md</a>.</li></ol><h2 id="_5-localization-vi-json-en-json-theme-tokens-observability-plan" tabindex="-1">5. Localization (<code>vi.json</code> + <code>en.json</code>), Theme Tokens &amp; Observability Plan <a class="header-anchor" href="#_5-localization-vi-json-en-json-theme-tokens-observability-plan" aria-label="Permalink to &quot;5. Localization (`vi.json` + `en.json`), Theme Tokens &amp; Observability Plan&quot;">​</a></h2><ul><li><strong>Key-Parallel Locale Synchronization:</strong> Every new or updated label in <code>chat.{channels,composer,threads,mentions,slash,scheduled,calls,preferences}.*</code> in <code>src/i18n/locales/{vi,en}/chat.json</code> is committed simultaneously in <code>vi</code> and <code>en</code> bundles on <code>brandhub-web</code> and mirrored in <code>brandhub-mobile-app/src/i18n/locales/en.json</code> + <code>src/i18n/locales/vi/common.json</code> (verified by <code>mobileI18nParity.test.ts</code> and <code>i18nCoverage.test.ts</code>).</li><li><strong>Light &amp; Dark Theme Architecture:</strong> Web components rely exclusively on semantic CSS custom properties (<code>bg-background</code>, <code>bg-card</code>, <code>text-foreground</code>, <code>text-muted-foreground</code>, <code>border-border</code>) and paired <code>dark:</code> utility classes; Mobile components consume <code>useAppPreferences().palette</code> (<code>src/theme/tokens.ts</code>) verified by <code>tokens.test.ts</code>.</li><li><strong>Structured Telemetry &amp; Rollback Safety:</strong> Every boundary logs <code>X-Request-Id</code>, latency, and classified <code>ErrorCode</code> while redacting tokens/PII. Additive schema migrations preserve backward-compatible rollback without dropping historical audit or ledger data.</li></ul><h2 id="_6-engineering-risks-mitigations" tabindex="-1">6. Engineering Risks &amp; Mitigations <a class="header-anchor" href="#_6-engineering-risks-mitigations" aria-label="Permalink to &quot;6. Engineering Risks &amp; Mitigations&quot;">​</a></h2><ul><li><strong>Scheduled Message Sender Removed Before Send Time:</strong> Dispatcher re-validates Workspace &amp; channel membership at fire time; if removed, cancels scheduled message without posting.</li></ul>',15)])])}const g=t(c,[["render",n]]);export{p as __pageData,g as default};
